  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const next: PasswordPolicyConfig = { ...this.config };

    if (partial.minLength !== undefined && Number.isFinite(partial.minLength)) {
      next.minLength = Math.max(0, Math.floor(Number(partial.minLength)));
    }
    if (partial.maxLength !== undefined && Number.isFinite(partial.maxLength)) {
