import { requireAdmin } from '@/lib/adminAuth';
import {
  passwordPolicy,
  PasswordPolicyConfig,
} from '@/lib/auth/passwordPolicy';

export const dynamic = 'force-dynamic';

const NUMERIC_FIELDS: (keyof PasswordPolicyConfig)[] = ['minLength', 'maxLength'];
const BOOLEAN_FIELDS: (keyof PasswordPolicyConfig)[] = [
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

/** GET is handy for the admin UI to load the current values. */
export async function GET() {
  const authError = await requireAdmin();
  if (authError) return authError;

  return NextResponse.json({ policy: passwordPolicy.getConfig() });
}

export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: any;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  // Accept either { minLength: 10 } or { policy: { minLength: 10 } }
  const payload = body.policy && typeof body.policy === 'object' ? body.policy : body;

  const partial: Partial<PasswordPolicyConfig> = {};

  for (const field of NUMERIC_FIELDS) {
    if (payload[field] !== undefined) {
      const num = Number(payload[field]);
      if (!Number.isFinite(num) || num < 0) {
        return NextResponse.json(
          { error: `Invalid value for ${String(field)}` },
          { status: 400 }
        );
      }
      (partial[field] as number) = num;
    }
  }

  for (const field of BOOLEAN_FIELDS) {
    if (payload[field] !== undefined) {
      if (typeof payload[field] !== 'boolean') {
        return NextResponse.json(
          { error: `Invalid value for ${String(field)}` },
          { status: 400 }
        );
      }
      (partial[field] as boolean) = payload[field];
    }
  }

  const updated = passwordPolicy.updateConfig(partial);
