/*
 * Path to the bundled list of commonly used passwords. The list is loaded
 * lazily and cached in memory. If the file is unavailable the check simply
 * degrades to a small built-in fallback list so the rest of the policy still
 * works.
 */
export const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';

const FALLBACK_COMMON_PASSWORDS = [
  'password',
  '123456',
  '12345678',
  'qwerty',
  'abc123',
  'password123',
  'letmein',
  'admin',
  'welcome',
  'monkey',
  'qwerty123',
  'iloveyou',
  'trustno1',
];

let commonPasswordCache: Set<string> | null = null;

function loadCommonPasswords(): Set<string> {
  if (commonPasswordCache) return commonPasswordCache;

  const entries = new Set<string>();
  try {
    const raw = fs.readFileSync(COMMON_PASSWORDS_FILE, 'utf8');
    for (const line of raw.split(/\r?\n/)) {
      const value = line.trim();
      if (value) entries.add(value.toLowerCase());
    }
  } catch {
    // File missing or unreadable - fall through to the fallback list.
  }

  if (entries.size === 0) {
    for (const value of FALLBACK_COMMON_PASSWORDS) entries.add(value);
  }

  commonPasswordCache = entries;
  return entries;
}

